head.script:
scwin.screenId = "jldinf90700";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "a_62", attr: "src", fn: function () { return "http://" + String(dma_map.get("hpage")); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_corpRegNoP_txt", fn: function(){ return ((dma_map.get("corpRegNoP") ?? (() => { throw new Error("unresolved:" + "map.corpRegNoP"); })()) !== '-'); } }, { id: "if_bzRegNoP_txt", fn: function(){ return ((dma_map.get("bzRegNoP") ?? (() => { throw new Error("unresolved:" + "map.bzRegNoP"); })()) !== '--'); } }, { id: "if_cntrCd_txt", fn: function(){ return ((dma_map.get("cntrCd") ?? (() => { throw new Error("unresolved:" + "map.cntrCd"); })()) === '410'); } }, { id: "if_acntclsMmdd1_txt", fn: function(){ return ((dma_map.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd1"); })()) !== ''); } }, { id: "if_acntclsMmdd2_txt", fn: function(){ return ((dma_map.get("acntclsMmdd2") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd2"); })()) !== ''); } }, { id: "if_acntclsMmdd3_txt", fn: function(){ return ((dma_map.get("acntclsMmdd3") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd3"); })()) !== ''); } }, { id: "if_acntclsMmdd4_txt", fn: function(){ return ((dma_map.get("acntclsMmdd4") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd4"); })()) !== ''); } }, { id: "if_acntclsMmdd5_txt", fn: function(){ return ((dma_map.get("acntclsMmdd5") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd5"); })()) !== ''); } }, { id: "if_acntclsMmdd6_txt", fn: function(){ return ((dma_map.get("acntclsMmdd6") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd6"); })()) !== ''); } }, { id: "if_acntclsMmdd7_txt", fn: function(){ return ((dma_map.get("acntclsMmdd7") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd7"); })()) !== ''); } }, { id: "if_acntclsMmdd8_txt", fn: function(){ return ((dma_map.get("acntclsMmdd8") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd8"); })()) !== ''); } }, { id: "if_acntclsMmdd9_txt", fn: function(){ return ((dma_map.get("acntclsMmdd9") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd9"); })()) !== ''); } }, { id: "if_acntclsMmdd10_txt", fn: function(){ return ((dma_map.get("acntclsMmdd10") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd10"); })()) !== ''); } }, { id: "if_acntclsMmdd11_txt", fn: function(){ return ((dma_map.get("acntclsMmdd11") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd11"); })()) !== ''); } }, { id: "if_acntclsMmdd12_txt", fn: function(){ return ((dma_map.get("acntclsMmdd12") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd12"); })()) !== ''); } }, { id: "if_bfsplitComNm", fn: function(){ return ((dma_map.get("bfsplitComNm") ?? (() => { throw new Error("unresolved:" + "map.bfsplitComNm"); })()) !== ''); } }, { id: "tr_106", fn: function(){ return ((dma_map.get("bfsplitComNm") ?? (() => { throw new Error("unresolved:" + "map.bfsplitComNm"); })()) !== ''); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "btn_openCorpModList", fn: function () { return String(dma_map.get("comNm")); } },
        { childId: "__rb11", fn: function () { return "[" + String(dma_map.get("zipcd1")) + "-" + String(dma_map.get("zipcd2")) + "]"; } },
        { childId: "__rb12", fn: function () { return String(dma_map.get("addr")) + " " + String(dma_map.get("dtlAddr")); } },
        { childId: "__rb13", fn: function () { return String(dma_map.get("engAddr")) + " " + String(dma_map.get("engDtlAddr")); } },
        { childId: "a_62", fn: function () { return String(dma_map.get("hpage")); } },
        { childId: "__rb17", fn: function () { return String(dma_map.get("acntclsMmdd1")) + "월"; } },
        { childId: "__rb18", fn: function () { return ", " + String(dma_map.get("acntclsMmdd2")) + "월"; } },
        { childId: "__rb19", fn: function () { return ", " + String(dma_map.get("acntclsMmdd3")) + "월"; } },
        { childId: "__rb20", fn: function () { return ", " + String(dma_map.get("acntclsMmdd4")) + "월"; } },
        { childId: "__rb21", fn: function () { return ", " + String(dma_map.get("acntclsMmdd5")) + "월"; } },
        { childId: "__rb22", fn: function () { return ", " + String(dma_map.get("acntclsMmdd6")) + "월"; } },
        { childId: "__rb23", fn: function () { return ", " + String(dma_map.get("acntclsMmdd7")) + "월"; } },
        { childId: "__rb24", fn: function () { return ", " + String(dma_map.get("acntclsMmdd8")) + "월"; } },
        { childId: "__rb25", fn: function () { return ", " + String(dma_map.get("acntclsMmdd9")) + "월"; } },
        { childId: "__rb26", fn: function () { return ", " + String(dma_map.get("acntclsMmdd10")) + "월"; } },
        { childId: "__rb27", fn: function () { return ", " + String(dma_map.get("acntclsMmdd11")) + "월"; } },
        { childId: "__rb28", fn: function () { return ", " + String(dma_map.get("acntclsMmdd12")) + "월"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf90700.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_openCorpModList_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_openCorpModList_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_openCorpModList_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.open_corpModList('' + dma_map.get("isurCd") + '','' + dma_map.get("comNm") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90700.btn_openCorpModList_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_closeWin_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_closeWin_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_closeWin_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90700.btn_closeWin_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_open_corpModList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_open_corpModList = async function () {
    const sbmOptions = {
        id: "tx_open_corpModList",
        method: "post",
        action: "/common/corp.do?method=corpModList",
        ref: "dma_openCorpModListReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf90700.tx_open_corpModList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.open_modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.open_modify = function () {
    /* sdd-asis-lifecycle:begin open_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.JLDINF90700 || { elements: [] });
    fn_popupCorpUpdReq(form);
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.open_corpModList
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_isurCd ipt_comNm
 * @returns
 * @hidden N
*/
scwin.open_corpModList = async function (ipt_isurCd, ipt_comNm) {
    /* sdd-asis-lifecycle:begin open_corpModList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = JLDINF90700;
    fm.isur_cd.value = ipt_isurCd;
    fm.com_nm.value = ipt_comNm;
    let _popupWindow;
    _popupWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/common/corp.do?method=corpModList", unresolved: "nav:" + "/common/corp.do?method=corpModList" }; })();
    fm.action = '/common/corp.do?method=corpModList';

    /* sdd-asis-lifecycle:end */
};
